package com.milano.quotation.storage;
import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.Query;import org.springframework.data.repository.query.Param;import java.time.Instant;import java.util.List;import java.util.Optional;import java.util.UUID;
public interface AssetObjectRepository extends JpaRepository<AssetObject,UUID>{Optional<AssetObject>findBySha256(String sha256);@Query(value="SELECT asset.* FROM asset_object asset WHERE asset.storage_state='temporary' AND asset.expires_at<:now AND NOT EXISTS (SELECT 1 FROM purchase_product_image image WHERE image.asset_id=asset.id)",nativeQuery=true)List<AssetObject>findExpiredUnreferenced(@Param("now")Instant now);}
